/**
 * Get the shared style component for the currently active cell in currently active sheet.
 * Only used for style supervisor.
 */
public function getSharedComponent(): self
{
    $activeSheet = $this->getActiveSheet();
    $selectedCell = $this->getActiveCell(); // e.g. 'A1'

    if ($activeSheet->cellExists($selectedCell)) {
        $xfIndex = $activeSheet->getCell($selectedCell)->getXfIndex();
    } else {
        $xfIndex = 0;
    }

    return $activeSheet->getParentOrThrow()->getCellXfByIndex($xfIndex);
}

/**
 * Create a new cell at the specified coordinate.
 *
 * @param string $coordinate Coordinate of the cell
 *
 * @return Cell Cell that was created
 *              WARNING: Because the cell collection can be cached to reduce memory, it only allows one
 *              "active" cell at a time in memory. If you assign that cell to a variable, then select
 *              another cell using getCell() or any of its variants, the newly selected cell becomes
 *              the "active" cell, and any previous assignment becomes a disconnected reference because
 *              the active cell has changed.
 */
public function createNewCell(Worksheet $worksheet, $coordinate): Cell
{
    [$column, $row, $columnString] = Coordinate::indexesFromString($coordinate);
    $cell = new Cell(null, DataType::TYPE_NULL, $worksheet);
    $worksheet->getCellCollection()->add($coordinate, $cell);

    $highestColumn = Coordinate::columnIndexFromString($worksheet->getHighestColumn());
    $highestRow = $worksheet->getHighestRow();
    if ($column > $highestColumn || $row > $highestRow) {
        $worksheet->adjustCachedHighestRowAndColumn(max($column, $highestColumn), max($row, $highestRow));
    }

    // Cell needs appropriate xfIndex from dimensions records
    //    but don't create dimension records if they don't already exist
    $rowDimensions = $worksheet->getRowDimensions();
    $columnDimensions = $worksheet->getColumnDimensions();
    $rowDimension = $rowDimensions[$row] ?? null;
    $columnDimension = $columnDimensions[$columnString] ?? null;

    $defaultXfIndex = 0;
    $styleParent = isset($this->parent) ? $this->parent : null;
    $worksheetParent = $worksheet->getParent();
    if ($this->isSupervisor && $styleParent instanceof Spreadsheet) {
        $defaultXfIndex = $styleParent->getDefaultStyle()->getIndex();
    } elseif ($worksheetParent instanceof Spreadsheet) {
        $defaultXfIndex = $worksheetParent->getDefaultStyle()->getIndex();
    }

    if ($rowDimension !== null) {
        $rowXf = (int) $rowDimension->getXfIndex();
        if ($rowXf > 0) {
            $cell->setXfIndex($rowXf);
        } else {
            $cell->setXfIndex($defaultXfIndex);
        }
    } elseif ($columnDimension !== null) {
        $colXf = (int) $columnDimension->getXfIndex();
        if ($colXf > 0) {
            $cell->setXfIndex($colXf);
        } else {
            $cell->setXfIndex($defaultXfIndex);
        }
    } else {
        $cell->setXfIndex($defaultXfIndex);
    }

    return $cell;
}

